// Headless check of the respondent prototype logic. Run: node respondent-sim.js [path to Respondent.dc.html]
const fs = require('fs');
const file = process.argv[2] || 'Respondent.dc.html';
const src = fs.readFileSync(file, 'utf8');
const js = src.match(/data-dc-script[^>]*>\n([\s\S]*?)\n<\/script>/)[1];
class DCLogic { constructor() { this.props = {}; } setState(p) { Object.assign(this.state, p); } }
const Component = new Function('DCLogic', js + '\nreturn Component;')(DCLogic);
const c = new Component(); const ev = (v) => ({ target: { value: v, checked: v } });
let fails = 0; const ok = (cond, msg) => { if (!cond) { fails += 1; console.log('FAIL', msg); } else console.log('ok  ', msg); };
let r = c.renderVals();
ok(r.isAbout && r.showNav && r.chapters.length === 5 && r.chapters.map(x => x.label).join('|') === 'About you|Submitting|Approving|Paying|Wrap up', 'about screen with five chapters');
ok(r.startDisabled, 'start disabled without name and role');
r.chapters[2].go(); r = c.renderVals(); ok(r.isArea && r.areaName === 'Approving' && r.visible.length === 2, 'free navigation to Approving shows two cards');
r.chapters[0].go(); r = c.renderVals(); r.setName(ev('Dana Okafor')); r.setRole(ev('Finance')); r = c.renderVals(); ok(!r.startDisabled, 'start enabled'); r.start(); r = c.renderVals();
ok(r.areaName === 'Submitting' && r.nextLabel === 'Continue to Approving', 'start lands on Submitting');
r.visible[0].p1Pick(); r = c.renderVals(); ok(r.visible[0].p1On && r.visible[0].note === 'Saved' && c.state.answers.i1.kind === 'agree', 'picking the proposed value is agree');
r.visible[1].p1Pick(); r = c.renderVals(); ok(c.state.answers.i2.kind === 'diff' && r.visible[1].commentOpen && r.visible[1].note === '' && r.visible[1].commentLabel === 'Could you tell us why you think the priority should be different?', 'another value opens a required comment');
r.visible[1].setText(ev('Two projects per trip.')); r = c.renderVals(); ok(r.visible[1].note === 'Saved' && r.chapterNote.startsWith('All 2'), 'reason completes the chapter');
r.visible[1].unPick(); r = c.renderVals(); ok(r.visible[1].unOn && r.visible[1].answerText === 'Two projects per trip.', 'switching to unclear keeps the typed text');
r.visible[1].p3Pick(); r = c.renderVals(); ok(c.state.answers.i2.kind === 'diff' && c.state.answers.i2.value === 'C', 'switching back to a value');
r.next(); r = c.renderVals(); ok(r.areaName === 'Approving', 'continue goes to the next chapter');
r.visible[0].p4Pick(); r = c.renderVals(); ok(c.state.answers.i3.kind === 'disagree' && r.visible[0].commentOpen, 'not needed opens a required comment'); r.visible[0].setText(ev('Not needed.')); r = c.renderVals(); ok(r.visible[0].note === 'Saved', 'not needed with a reason saves');
ok(r.visible[0].p1Cap === 'proposed' && r.visible[0].p1BdStyle === 'dashed' && r.visible[0].p2Cap === '', 'proposed pill is marked');
r.visible[1].toggleDetails(); r = c.renderVals(); ok(r.visible[1].detailsOpen && r.visible[1].detail.includes('From the spreadsheet'), 'View more opens the details above the rating row');
r.visible[1].p2Pick(); r = c.renderVals(); ok(r.visible[1].showCommentToggle && !r.visible[1].commentOpen, 'agree: comment optional and closed'); r.visible[1].toggleComment(); r = c.renderVals(); ok(r.visible[1].commentOpen && r.visible[1].detailsOpen && r.visible[1].commentLabel === 'Comment, optional', 'optional comment opens beside the open details');
r.next(); r = c.renderVals(); r.next(); r = c.renderVals(); ok(r.isWrap, 'continue past Paying reaches Wrap up');
ok(r.hasGaps && r.gapLine === '2 items still unrated.' && r.gapChapter === 'Paying', 'wrap up names the gap and the chapter');
ok(r.submitDisabled && r.submitNote.includes('2 unrated items') && r.submitNote.includes('confidence'), 'submit lists what is missing');
r.gapGo(); r = c.renderVals(); ok(r.isArea && r.areaName === 'Paying', 'go to gap lands on Paying');
r.visible[0].p1Pick(); r = c.renderVals(); r.visible[1].p3Pick(); r = c.renderVals();
r.chapters[4].go(); r = c.renderVals(); ok(!r.hasGaps && r.sections.map(x => x.title + ':' + x.rows.length).join('|') === 'You suggested a lower priority:1|You said these are not needed:1', 'wrap up groups by suggestion: ' + r.sections.map(x => x.title).join(' / '));
ok(r.tally.map(x => x.n + ' ' + x.label).join(', ') === '4 agreed, 0 higher priority, 1 lower priority, 1 not needed, 0 unclear', 'tally: ' + r.tally.map(x => x.n + ' ' + x.label).join(', '));
ok(r.summaryLine === '4 agreed, 1 changed, 1 not needed, 0 unclear', 'summary line: ' + r.summaryLine);
r.sections[0].rows[0].edit(); r = c.renderVals(); ok(r.areaName === 'Submitting', 'change link goes to the item chapter'); r.chapters[4].go(); r = c.renderVals();
r.confidence[3].pick(); r = c.renderVals(); r.toggleSigned(ev(true)); r = c.renderVals(); ok(!r.submitDisabled, 'submit enabled');
r.submit(); r = c.renderVals(); ok(r.submitLabel === 'Submitting' && r.submitDisabled, 'loading state');
setTimeout(() => {
r = c.renderVals(); ok(r.isDone && r.thanks === 'Thank you, Dana.' && r.headerNote === 'Submitted', 'done screen');
r.reopen(); r = c.renderVals(); ok(r.isWrap && !r.signed && r.submitDisabled, 'change my answers clears the confirmation');
r.toggleBlind(); r = c.renderVals(); ok(r.isAbout && r.answeredCount === 0 && r.confidence.every(k => !k.active) && !r.submittedAt, 'blind toggle resets the flow');
r.start(); r = c.renderVals(); ok(r.visible[0].p1Cap === '' && r.visible[0].p1BdStyle === 'solid', 'blind cards show no proposed marker');
r.visible[0].p2Pick(); r = c.renderVals(); ok(r.visible[0].note === 'Saved' && c.state.answers.i1.kind === 'pick', 'pick saves');
r.chapters[4].go(); r = c.renderVals(); ok(r.summaryLine.startsWith('1 rated'), 'blind summary wording: ' + r.summaryLine);
r.cycleLink(); r = c.renderVals(); ok(r.linkLabel === 'public, same device again' && r.isAbout && r.isReturning && r.answeredCount === 4, 'returning public link');
r.resumeGo(); r = c.renderVals(); ok(r.isArea && r.areaName === 'Paying', 'carry on lands on the first unanswered chapter');
r.cycleLink(); r = c.renderVals(); ok(r.linkLabel === 'personal' && r.isPersonal && !r.askFields && !r.startDisabled, 'personal link: no fields, start enabled');
ok(Object.values(c.state.answers).every(a => a.kind === 'pick'), 'personal seed respects blind mode');
r.toggleBlind(); r = c.renderVals(); ok(Object.values(c.state.answers).every(a => a.kind !== 'pick'), 'reseeded when leaving blind mode');
r.cycleLink(); r = c.renderVals(); ok(r.isClosed && r.closedDetail && r.closedLine.startsWith('You answered 4'), 'closed page, personal detail shown');
r.cycleLink(); r = c.renderVals(); ok(r.isRevoked && r.headerNote === 'Inactive', 'revoked page');
r.cycleLink(); r = c.renderVals(); ok(r.isAbout && c.state.name === '' && r.answeredCount === 0, 'open link starts fresh');
r.toggleOffline(); r = c.renderVals(); ok(r.isOffline && r.headerNote === 'Not saved', 'offline banner and header');
r.toggleLayout(); r = c.renderVals(); r.start(); r = c.renderVals(); ok(r.layoutLabel === 'one item per screen' && r.visible.length === 1 && r.nextLabel === 'Continue' && r.chapterNote.startsWith('Item 1 of 2'), 'one item per screen option');
r.next(); r = c.renderVals(); ok(r.visible[0].ref === 'CL-02', 'continue moves to the second item'); r.next(); r = c.renderVals(); ok(r.areaName === 'Approving' && r.visible[0].ref === 'CL-03', 'then to the next chapter');
r.back(); r = c.renderVals(); ok(r.areaName === 'Submitting' && r.visible[0].ref === 'CL-02', 'back returns to the last item of the previous chapter');
r.toggleLayout(); r = c.renderVals(); ok(r.visible.length === 2, 'back to chapters');
ok(r.accent === '#1F4F7A' && r.chapters[1].bg === '#1F4F7A', 'accent drives the active chapter');
console.log(fails ? fails + ' failures' : 'all checks passed');
process.exit(fails ? 1 : 0);
}, 800);
